import TotalField from "./totalfield";
import { regenerateIds } from "./regenerateIds.mjs";
import TotalSortable from "./total-sortable";
import { collectScopedFieldValues } from "./fieldCollection.mjs";
import { missingIdPropertyMessage } from "./deckItem";

//-----------------------------------------------
// Total CMS Deck Table Field
//-----------------------------------------------
export default class DeckTableField extends TotalField {

    constructor(container, settings) {
        super(container, settings);

        this.schemaref = container.dataset.schemaref || container.dataset.deckref || '';
        this.minItems = parseInt(this.settings.minItems) || 0;
        this.maxItems = parseInt(this.settings.maxItems) || -1;

		this.valid = true;
		this.sortable = null;

        // Get the table body and template
        this.tableBody = this.container.querySelector('.deck-table-body');
        this.template = this.container.querySelector('template.deck-table-template');

        // Initialize existing rows
        const rows = this.tableBody?.querySelectorAll('.deck-table-row') || [];
        for (const row of rows) {
            this.initRow(row);
        }
        this.initSortable();

        // Initialize oid counter based on existing items
        this.initOidCounter();

        // Setup add button
        this.addButton = this.container.querySelector('.cms-add');
        this.addButton?.addEventListener('click', () => this.addRow());

        this.updateAddButton();

        // Propagate sub-row edits to the deck table's own changed handler.
        // Ignore events the table itself dispatched: when nested inside a
        // card, deckTable.changed() → super.changed() emits subfield-change
        // from this.container, and this listener (also on this.container)
        // would self-trigger and recurse.
        this.container.addEventListener('subfield-change', e => {
            if (e.target === this.container) return;
            this.changed();
        });
        // …and sub-field saves back down: a persisted delete, an autosaved
        // dialog or a featured star should not leave this composite dirty.
        this.listenForSubFieldSaves();
    }

    initOidCounter() {
        const existingCount = this.tableBody?.querySelectorAll('.deck-table-row').length || 0;
        this.oidCounter = existingCount;
    }

    getNextOid() {
        this.oidCounter++;
        return this.oidCounter;
    }

    initSortable() {
        if (this.sortable) {
            this.sortable.destroy();
        }

        if (!this.tableBody) return;

        this.sortable = new TotalSortable(this.tableBody, {
            handle: '.sort-handle',
            onEnd: () => this.changed(),
        });
    }

    /**
     * Regenerate unique IDs in a cloned element to prevent duplicate id/for collisions.
     */
    regenerateIds(element) {
        return regenerateIds(element);
    }

    initRow(row) {
        // Store reference on the DOM element
        row.deckTableRow = this;

        // Setup action button listeners. The row's own delete lives in the
        // actions column at the END of the row; an image or file cell carries
        // an action bar with a trash button of its own before it, so a bare
        // `button.trash` would bind row removal to the image's delete.
        const trash = row.querySelector(':scope > .deck-table-actions button.trash');
        trash?.addEventListener('click', () => this.removeRow(row));

        // Process fields in the row
        this.form?.processFields();

        // Wire conditional visibility for this row, scoped to the row so a field's
        // `watch` resolves against its sibling cells (mirrors DeckItem.initVisibility,
        // which scopes to the item dialog). Without this, visibility/disable settings
        // are inert in deck-table layouts.
        this.initRowVisibility(row);
    }

    initRowVisibility(row) {
        if (!this.form?.visibility) return;
        const fields = [];
        row.querySelectorAll('.form-field').forEach(el => {
            if (el.totalfield) fields.push(el.totalfield);
        });
        if (fields.length > 0) {
            this.form.visibility.initializeScope(row, fields);
        }
    }

    updateAddButton() {
        if (!this.addButton) return;
        const rowCount = this.tableBody?.querySelectorAll('.deck-table-row').length || 0;
        const atMax = this.maxItems > -1 && rowCount >= this.maxItems;
        this.addButton.disabled = atMax;
    }

    addRow() {
        if (!this.template || !this.tableBody) return;

        const rowCount = this.tableBody.querySelectorAll('.deck-table-row').length;
        if (this.maxItems > -1 && rowCount >= this.maxItems) return;

        const clone = this.template.content.cloneNode(true);
        this.regenerateIds(clone);

        // Mark the row unsaved BEFORE its fields initialize: a nested image or
        // file field reads this (TotalField.parentIsSaved) when it builds its
        // dropzone, and starts with auto-processing off, so a drop into a row
        // that does not exist on disk yet waits for the parent save — which is
        // what gives the row its shape and id. Same lifecycle as DeckField.addItem;
        // saved() clears `.unsaved` from descendants after the save.
        clone.querySelector('.deck-table-row')?.classList.add('unsaved');

        this.tableBody.appendChild(clone);

        // Get the newly added row
        const rows = this.tableBody.querySelectorAll('.deck-table-row');
        const newRow = rows[rows.length - 1];

        this.initRow(newRow);

        // Auto-populate ID if autogen pattern exists
        this.autoPopulateId(newRow);

        this.changed();
        this.updateAddButton();
    }

    autoPopulateId(row) {
        const labelPattern = this.container.dataset.deckLabelPattern || '${id}';
        const idInput = row.querySelector("input[name='id']");
        if (!idInput) return;

        // Check for auto-generating ID patterns
        const hasAutoPattern = /\$\{(uuid|uid|oid|timestamp|now|currentyear|currentmonth|currentday)/.test(labelPattern);
        if (!hasAutoPattern) return;

        const now = new Date();
        const fieldData = {
            now: Date.now(),
            timestamp: now.toISOString().slice(0, -5).replace(/-|:/g, ''),
            uuid: this.generateUuid(),
            uid: Math.random().toString(36).substring(2, 9),
            oid: this.getNextOid(),
            currentyear: now.getFullYear().toString(),
            currentyear2: now.getFullYear().toString().slice(-2),
            currentmonth: String(now.getMonth() + 1).padStart(2, '0'),
            currentday: String(now.getDate()).padStart(2, '0'),
        };

        let generatedId = labelPattern.replace(/\${(.*?)}/g, (match, key) => {
            if (key.startsWith('oid-') && /^oid-0+$/.test(key)) {
                const zeros = key.substring(4);
                const paddingLength = zeros.length;
                return this.getNextOid().toString().padStart(paddingLength, '0');
            }
            return fieldData[key] || '';
        });

        idInput.value = generatedId.trim();
    }

    generateUuid() {
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            const r = Math.random() * 16 | 0;
            const v = c == 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });
    }

    removeRow(row) {
        row.remove();
        this.changed();
        this.updateAddButton();
    }

    getValue() {
        const deckData = {};

        if (!this.tableBody) return deckData;

        const rows = this.tableBody.querySelectorAll('.deck-table-row');
        for (const row of rows) {
            // Collect only the row's own top-level fields; composite sub-fields
            // (e.g. an image's `name`/"Filename") must not leak into the row and
            // overwrite its real properties. See fieldCollection.mjs.
            const rowData = collectScopedFieldValues(row);
            const itemId = rowData.id ? String(rowData.id) : '';

            if (itemId) {
                deckData[itemId] = rowData;
            }
        }

        return Object.keys(deckData).length === 0 ? {} : deckData;
    }

    setValue(value) {
        console.warn("DeckTableField.setValue() is not implemented", value);
    }

    clearValue() {
        if (this.tableBody) {
            this.tableBody.innerHTML = '';
        }
    }

    isUnsaved() {
        const unsavedChildren = this.container.querySelectorAll('.unsaved');
        return this.container.classList.contains('unsaved') || unsavedChildren.length > 0;
    }

    saved() {
        super.saved();
        const unsavedChildren = this.container.querySelectorAll('.unsaved');
        unsavedChildren.forEach(el => el.classList.remove('unsaved'));
    }

    error(message) {
        this.input.setCustomValidity(message);
        super.error(message);
    }

    changed() {
        this.input.setCustomValidity('');
        super.changed();
    }

    validate() {
        this.input.setCustomValidity('');

        if (!this.isVisible()) return true;

        let isValid = true;

        const rows = this.tableBody?.querySelectorAll('.deck-table-row') || [];

        // Check if required and empty
        if (this.input.required && rows.length === 0) {
            const errorMessage = 'Please add at least one.';
            this.input.setCustomValidity(errorMessage);
            this.input.reportValidity();
            this.error(errorMessage);
            this.valid = false;
            return this.valid;
        }

        // Check minimum item count
        if (this.minItems > 0 && rows.length < this.minItems) {
            const errorMessage = `Please add at least ${this.minItems} items`;
            this.input.setCustomValidity(errorMessage);
            this.input.reportValidity();
            this.error(errorMessage);
            this.valid = false;
            return this.valid;
        }

        // Check maximum item count
        if (this.maxItems > -1 && rows.length > this.maxItems) {
            const errorMessage = `Maximum ${this.maxItems} items allowed`;
            this.input.setCustomValidity(errorMessage);
            this.input.reportValidity();
            this.error(errorMessage);
            this.valid = false;
            return this.valid;
        }

        const itemIds = [];

        for (const row of rows) {
            // Get the ID from this row
            const idInput = row.querySelector("input[name='id']");
            const itemId = idInput ? String(idInput.value) : '';

            if (itemId.length === 0) {
                const errorMessage = idInput ? 'Item ID cannot be empty' : missingIdPropertyMessage(this.schemaref);
                this.error(errorMessage);
                isValid = false;
                continue;
            }

            if (itemIds.includes(itemId)) {
                const errorMessage = `Duplicate ID found: ${itemId}`;
                this.error(errorMessage);
                isValid = false;
                continue;
            }

            itemIds.push(itemId);

            // Validate fields inside this row
            const formFieldContainers = row.querySelectorAll('.form-field');
            for (const container of formFieldContainers) {
                if (container.totalfield && typeof container.totalfield.validate === 'function') {
                    if (!container.totalfield.validate()) {
                        isValid = false;
                    }
                }
            }
        }

        this.valid = isValid;
        return this.valid;
    }

    schema() {
        return {
            type: "deck",
            fieldset: this.type,
            schemaref: this.schemaref
        };
    }
}
